{
  "name": "@cavendo/mcp-server",
  "version": "0.1.0",
  "description": "MCP server for Cavendo Engine - AI agent workflow platform",
  "type": "module",
  "bin": {
    "cavendo-mcp": "bin/cavendo-mcp.js"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc",
