          "name": "A2A Editor"
        }
      ]
    },
    "customEditors": [
      {
        "viewType": "a2aAgentCard.editor",
        "displayName": "A2A Agent Card Editor",
        "selector": [
          {
            "filenamePattern": "*.agentcard.json"
          },
          {
            "filenamePattern": "agent-card.json"
          },
          {
            "filenamePattern": "agent.json"
          }
        ],
        "priority": "option"
      }
    ],
    "commands": [
      {
        "command": "a2aAgentCard.openFileWith",
        "title": "A2A: Open Current File as Agent Card"
      }
    ],
    "configuration": {
      "title": "A2A Editor",
      "properties": {
        "a2aAgentCard.mcp.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Run an in-process MCP (Model Context Protocol) server so external tools (Claude Code, Cursor, Cline, ...) can use the A2A tools."
        },
        "a2aAgentCard.mcp.host": {
          "type": "string",
          "default": "127.0.0.1",
          "description": "Host the MCP server binds to. Use 127.0.0.1 to restrict to this machine."
        },
        "a2aAgentCard.mcp.port": {
          "type": "number",
          "default": 39627,
          "minimum": 1,
          "maximum": 65535,
          "description": "Port the MCP server listens on."
        }
      }
    },
    "chatParticipants": [
      {
        "id": "a2aAgentCard.chat",
        "name": "a2a",
        "fullName": "A2A Agent Card",
        "description": "Ask about agent cards, open them, or test A2A agents",
        "isSticky": true,
        "commands": [
          {
            "name": "open",
            "description": "Open an agent card file in the A2A Editor"
          },
          {
            "name": "connect",
            "description": "Fetch and display an agent card from a URL"
          },
          {
            "name": "test",
            "description": "Send a test message to an A2A agent"
          }
        ]
      }
    ],
    "languageModelTools": [
      {
        "name": "a2aAgentCard_fetchAgentCard",
        "displayName": "Fetch A2A Agent Card",
        "toolReferenceName": "fetchAgentCard",
        "canBeReferencedInPrompt": true,
        "icon": "$(globe)",
        "modelDescription": "Fetch an A2A agent card from a URL. Tries well-known paths (/.well-known/agent.json, /.well-known/agent-card.json) before falling back to the direct URL. Returns the full agent card JSON with a summary of the agent's name, endpoint, description, and skills.",
        "inputSchema": {
          "type": "object",
          "required": [
            "url"
          ],
          "properties": {
            "url": {
              "type": "string",
              "description": "The URL of the A2A agent or direct path to an agent card JSON file"
            }
          }
        }
      },
      {
        "name": "a2aAgentCard_validateAgentCard",
        "displayName": "Validate A2A Agent Card",
        "toolReferenceName": "validateAgentCard",
        "canBeReferencedInPrompt": true,
        "icon": "$(check)",
        "modelDescription": "Validate a JSON string as an A2A agent card. Checks for required fields (name, url) and reports present optional fields (skills, capabilities, provider, securitySchemes, etc.). Returns a validation summary including whether the card is valid, which fields are present or missing, and details about skills and capabilities.",
        "inputSchema": {
          "type": "object",
          "required": [
            "content"
          ],
          "properties": {
            "content": {
              "type": "string",
              "description": "The JSON string to validate as an A2A agent card"
            }
          }
        }
      },
      {
        "name": "a2aAgentCard_sendMessage",
        "displayName": "Send Message to A2A Agent",
        "toolReferenceName": "sendA2AMessage",
        "canBeReferencedInPrompt": true,
        "icon": "$(comment)",
        "modelDescription": "Send a test message to an A2A agent using the JSON-RPC 2.0 message/send method. Posts the message to the agent's URL and returns the response. Use this to test if an A2A agent is responding correctly.",
        "inputSchema": {
          "type": "object",
          "required": [
            "url",
            "message"
          ],
          "properties": {
            "url": {
              "type": "string",
              "description": "The A2A agent endpoint URL to send the message to"
            },
            "message": {
              "type": "string",
              "description": "The text message to send to the agent"
            }
          }
        }
      }
    ],
    "mcpServerDefinitionProviders": [
      {
        "id": "a2aAgentCard.mcp",
        "label": "A2A Agent Card"
      }
