{
  "name": "@jobly/backend",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "build": "prisma generate && nest build",
    "format": "prettier --write \"src/**/*.ts\" \"test/**/*.ts\"",
    "start": "nest start",
    "start:dev": "nest start --watch",
    "dev": "nest start --watch",
    "start:debug": "nest start --debug --watch",
    "start:prod": "node dist/main",
    "auth:schema": "pnpm dlx @better-auth/cli@latest generate --config ./src/lib/auth.ts --output ./prisma/schema.prisma",
    "auth:setup": "pnpm run auth:schema && prisma migrate dev && prisma generate",
    "prisma:generate": "prisma generate",
    "prisma:migrate": "prisma migrate dev",
    "prisma:studio": "prisma studio",
    "seed:embeddings": "ts-node src/scripts/seed-embeddings.ts",
    "seed:mock-apps": "ts-node src/scripts/seed-mock-applications.ts",
    "lint": "eslint .",
    "test": "pnpm -w vitest run --config apps/backend/vitest.config.ts",
    "test:watch": "pnpm -w vitest --config apps/backend/vitest.config.ts",
    "test:ui": "pnpm -w vitest --ui --config apps/backend/vitest.config.ts",
    "test:cov": "pnpm -w vitest run --coverage --config apps/backend/vitest.config.ts"
  },
  "nx": {
    "targets": {
      "build": {
        "executor": "nx:run-commands",
        "options": {
          "command": "webpack-cli build",
          "args": [
            "--node-env=production"
          ],
          "cwd": "apps/backend"
        },
        "configurations": {
          "development": {
            "args": [
              "--node-env=development"
            ]
          }
        }
      },
      "prune-lockfile": {
        "dependsOn": [
          "build"
        ],
        "cache": true,
        "executor": "@nx/js:prune-lockfile",
        "outputs": [
          "{workspaceRoot}/apps/backend/dist/package.json",
          "{workspaceRoot}/apps/backend/dist/pnpm-lock.yaml"
        ],
        "options": {
          "buildTarget": "build"
        }
      },
      "copy-workspace-modules": {
        "dependsOn": [
          "build"
        ],
        "cache": true,
        "outputs": [
          "{workspaceRoot}/apps/backend/dist/workspace_modules"
        ],
        "executor": "@nx/js:copy-workspace-modules",
        "options": {
          "buildTarget": "build"
        }
      },
      "prune": {
        "dependsOn": [
          "prune-lockfile",
          "copy-workspace-modules"
        ],
        "executor": "nx:noop"
      },
      "serve": {
        "continuous": true,
        "executor": "@nx/js:node",
        "defaultConfiguration": "development",
        "dependsOn": [
          "build"
        ],
        "options": {
          "buildTarget": "@jobly/backend:build",
          "runBuildTargetDependencies": false
        },
        "configurations": {
          "development": {
            "buildTarget": "@jobly/backend:build:development"
          },
          "production": {
            "buildTarget": "@jobly/backend:build:production"
          }
        }
      },
      "quality-gate": {
        "executor": "nx:noop",
        "dependsOn": [
          "lint",
          "test",
          "build"
        ]
      },
      "test": {
        "executor": "nx:run-commands",
        "options": {
          "command": "pnpm -w vitest run --config apps/backend/vitest.config.ts"
        }
      }
    }
