{
  "name": "codeserve-mcp",
  "displayName": "CodeServe MCP",
  "description": "Builds a robust knowledge graph of your codebase and provides an MCP server for LLM integration in VS Code and Cursor.",
  "version": "1.0.0",
  "publisher": "nolnoch",
  "author": "nolnoch",
  "icon": "assets/codeserve_icon.png",
  "repository": {
    "type": "git",
    "url": "https://github.com/nolnoch/codeserve"
  },
  "license": "AGPL-3.0",
  "engines": {
    "vscode": "^1.92.0"
  },
  "categories": [
    "Programming Languages",
    "Other"
  ],
  "keywords": [
    "mcp",
    "claude",
    "code intelligence",
    "python",
    "ast"
  ],
  "extensionKind": [
    "workspace",
    "ui"
  ],
  "activationEvents": [
    "onStartupFinished",
    "onLanguage:python",
    "onLanguage:typescript",
    "onLanguage:javascript",
    "onLanguage:typescriptreact",
    "onLanguage:javascriptreact",
    "onLanguage:vue"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "mcpServerDefinitionProviders": [
      {
        "id": "codeserve.mcpProvider",
        "label": "CodeServe MCP"
      }
    ],
    "commands": [
      {
        "command": "codeserve.startServer",
        "title": "CodeServe: Start MCP Server"
      },
      {
        "command": "codeserve.stopServer",
        "title": "CodeServe: Stop MCP Server"
      },
      {
        "command": "codeserve.restartServer",
        "title": "CodeServe: Restart MCP Server"
      },
      {
        "command": "codeserve.reindex",
        "title": "CodeServe: Reindex Workspace"
      },
      {
        "command": "codeserve.dumpIndexFiles",
        "title": "CodeServe: Dump Indexable Files"
      },
      {
        "command": "codeserve.clearGraph",
        "title": "CodeServe: Clear Knowledge Graph"
      },
      {
        "command": "codeserve.showStatus",
        "title": "CodeServe: Show Server Status"
      },
      {
        "command": "codeserve.registerClaudeCode",
        "title": "CodeServe: Copy MCP for Claude (command)"
      },
      {
        "command": "codeserve.copyMCPJson",
        "title": "CodeServe: Copy MCP for VS Code/Cursor (JSON)"
      },
      {
        "command": "codeserve.resetFirstRunPrompt",
        "title": "CodeServe: Reset First-Run Prompt"
      },
      {
        "command": "codeserve.showCallersAtCursor",
        "title": "CodeServe: Show Callers at Cursor"
      },
      {
        "command": "codeserve.showCalleesAtCursor",
        "title": "CodeServe: Show Callees at Cursor"
      },
      {
        "command": "codeserve.showCallGraphAtCursor",
        "title": "CodeServe: Show Call Graph at Cursor"
      },
      {
        "command": "codeserve.clearIndexCache",
        "title": "CodeServe: Clear Index Cache"
      },
      {
        "command": "codeserve.diagnoseLanguageServers",
        "title": "CodeServe: Diagnose Language Servers"
      }
    ],
    "configuration": {
      "title": "CodeServe MCP",
      "properties": {
        "codeserve.servicePort": {
          "type": "number",
          "default": 8000,
          "description": "Port for the code graph service"
        },
        "codeserve.autoStart": {
          "type": "boolean",
          "default": true,
          "description": "Automatically start the code graph service on activation (first run will prompt)"
        },
        "codeserve.pythonPath": {
          "type": "string",
          "default": "python",
          "description": "Path to Python executable"
        },
        "codeserve.indexOnStart": {
          "type": "boolean",
          "default": true,
          "description": "Automatically index workspace on startup"
        },
        "codeserve.indexing.exclude": {
          "type": "string",
          "default": "**/{node_modules,.git,.venv,venv,env,.env,__pycache__,.tox,.pytest_cache,.mypy_cache,.direnv,site-packages,dist,build,out,.codeserve}/**",
          "description": "Glob pattern of paths to exclude from indexing"
        },
        "codeserve.indexTestFiles": {
          "type": "boolean",
          "default": true,
          "description": "Include test files in indexing and symbol search results"
        },
        "codeserve.watchFiles": {
          "type": "boolean",
          "default": true,
          "description": "Watch for file changes and update index"
        },
        "codeserve.indexing.incremental": {
          "type": "boolean",
          "default": true,
          "description": "Skip unchanged files during reindex"
        },
        "codeserve.analysis.hoverEnrichment": {
          "type": "boolean",
          "default": true,
          "description": "Use language server hover data to enrich types during indexing. Disable if your Python LS (e.g., Ruff) crashes on hover."
        },
        "codeserve.analysis.hoverThrottleMs": {
          "type": "number",
          "default": 0,
          "minimum": 0,
          "description": "Optional delay in milliseconds between hover requests during indexing to avoid overloading the language server."
        },
        "codeserve.mcpStdioPort": {
          "type": "number",
          "default": 3000,
          "description": "Port for MCP stdio server (for debugging)"
        },
        "codeserve.portAutoRetry": {
          "type": "boolean",
          "default": true,
          "description": "If true, automatically find the next available port when the configured port is in use"
        },
        "codeserve.portAutoRetryMax": {
          "type": "number",
          "default": 20,
          "minimum": 0,
          "description": "Maximum number of incremental ports to try when the configured port is in use"
        },
        "codeserve.calls.onDemand.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable on-demand caller/callee analysis using Language Server"
        },
        "codeserve.calls.maxDepth": {
          "type": "number",
          "default": 2,
          "minimum": 1,
          "maximum": 5,
          "description": "Maximum depth for call graph traversal"
        },
        "codeserve.calls.maxEdgesPerQuery": {
          "type": "number",
          "default": 500,
          "minimum": 10,
          "maximum": 5000,
          "description": "Maximum edges to return per call graph query"
        },
        "codeserve.calls.lsTimeoutMs": {
          "type": "number",
          "default": 800,
          "minimum": 100,
          "maximum": 5000,
          "description": "Timeout in milliseconds for Language Server operations"
        },
        "codeserve.calls.throttleMs": {
          "type": "number",
          "default": 10,
          "minimum": 0,
          "maximum": 100,
          "description": "Throttle delay in milliseconds between Language Server requests"
        },
        "codeserve.calls.computeTimeoutMs": {
          "type": "number",
          "default": 5000,
          "minimum": 1000,
          "maximum": 10000,
          "description": "Maximum time to wait for call graph computation (ms)"
        },
        "codeserve.calls.enableCompute": {
          "type": "boolean",
          "default": true,
          "description": "Enable on-demand call graph computation in MCP tools"
        },
        "codeserve.cpp.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable C++ language support (requires clangd or C/C++ extension)"
        },
        "codeserve.cpp.callHierarchy": {
          "type": "boolean",
          "default": false,
          "description": "Enable call hierarchy analysis for C++ files (creates 'calls' edges)"
        },
        "codeserve.cpp.references": {
          "type": "boolean",
          "default": false,
          "description": "Enable reference analysis for C++ files"
        },
        "codeserve.cpp.compileCommands": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": [],
          "description": "Custom paths to compile_commands.json files. Auto-detected when empty."
        },
        "codeserve.typescript.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable TypeScript/JavaScript language support"
        },
        "codeserve.typescript.callHierarchy": {
          "type": "boolean",
          "default": false,
          "description": "Enable call hierarchy analysis for TypeScript/JavaScript files (creates 'calls' edges)"
        },
        "codeserve.typescript.references": {
          "type": "boolean",
          "default": false,
          "description": "Enable reference analysis for TypeScript/JavaScript files"
        },
        "codeserve.typescript.jsDocTypes": {
          "type": "boolean",
          "default": true,
          "description": "Extract types from JSDoc comments in JavaScript files"
        },
        "codeserve.typescript.frameworkSupport": {
          "type": "boolean",
          "default": true,
          "description": "Enable React/Vue component detection and analysis"
        },
        "codeserve.typescript.includeNodeModules": {
          "type": "boolean",
          "default": false,
          "description": "Include node_modules in analysis (warning: can be slow)"
        },
        "codeserve.typescript.maxFileSize": {
          "type": "number",
          "default": 1048576,
          "description": "Maximum file size in bytes to analyze (default: 1MB)"
        },
        "codeserve.crossLanguage.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable cross-language reference analysis"
        },
        "codeserve.crossLanguage.staticFiles": {
          "type": "boolean",
          "default": true,
          "description": "Track static file imports across languages (JSON, YAML, Python files, etc.)"
        },
        "codeserve.crossLanguage.buildDependencies": {
          "type": "boolean",
          "default": true,
          "description": "Track build script dependencies (package.json scripts, pyproject.toml hooks, Makefiles)"
        },
        "codeserve.crossLanguage.confidenceThreshold": {
          "type": "number",
          "default": 0.7,
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum confidence score for cross-language relationships"
        },
        "codeserve.crossLanguage.maxSearchDepth": {
          "type": "number",
          "default": 3,
          "minimum": 1,
          "maximum": 10,
          "description": "Maximum directory depth for cross-language file resolution"
        },
        "codeserve.indexing.parallelWorkers": {
          "type": "number",
          "default": 4,
          "minimum": 1,
          "maximum": 16,
          "description": "Number of files to analyze in parallel during indexing"
        },
        "codeserve.indexing.batchSize": {
          "type": "number",
          "default": 12,
          "minimum": 1,
          "maximum": 100,
          "description": "Number of files to process before updating progress (ideally divisible by parallelWorkers)"
        },
        "codeserve.indexing.backendChunkSize": {
          "type": "number",
          "default": 50,
          "minimum": 10,
          "maximum": 200,
          "description": "Number of files to send to backend in one request"
        },
        "codeserve.calls.autoCompute": {
          "type": "boolean",
          "default": true,
          "description": "Automatically compute call graphs in background"
        },
        "codeserve.calls.computeOnSave": {
          "type": "boolean",
          "default": true,
          "description": "Compute call graphs when files are saved"
        },
        "codeserve.calls.computeBatchSize": {
          "type": "number",
          "default": 10,
          "minimum": 1,
          "maximum": 50,
          "description": "Number of symbols to compute in parallel"
        },
        "codeserve.calls.cacheExpiryHours": {
          "type": "number",
          "default": 24,
          "minimum": 1,
          "maximum": 168,
          "description": "Hours before cached call graphs expire"
        }
      }
    }
  },
  "scripts": {
    "vscode:prepublish": "npm run compile",
    "compile": "node esbuild.js --production",
    "compile:dev": "node esbuild.js",
    "watch": "node esbuild.js --watch",
    "pretest": "npm run compile:dev",
    "lint": "eslint src --ext ts || true",
    "test": "./test-all.sh",
    "test:mcp": "npm run compile:dev && node out/test/mcp-test-client.js",
    "test:integration": "npm run compile:dev && node out/test/integration-test.js",
    "test:standalone": "node out/mcp-stdio-wrapper.js",
    "package": "vsce package",
    "type-check": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/mocha": "^10.0.10",
    "@types/node": "^20.10.0",
    "@types/vscode": "^1.85.0",
    "@typescript-eslint/eslint-plugin": "^6.13.0",
    "@typescript-eslint/parser": "^6.13.0",
    "esbuild": "^0.25.9",
    "eslint": "^8.54.0",
    "typescript": "^5.3.0"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "axios": "^1.6.0",
    "eventsource": "^2.0.2",
    "minimatch": "^10.0.3",
