        "title": "Approve Plan and Switch to Agent Mode"
      },
      {
        "command": "llem.reloadMcpServers",
        "title": "Reload MCP Servers"
      },
      {
        "command": "llem.listMcpServers",
        "title": "List MCP Servers"
      },
      {
        "command": "llem.syncCodexMcpServers",
        "title": "Sync Codex MCP Servers"
      },
      {
        "command": "llem.importMcpFromGitHub",
        "title": "Import MCP Server from GitHub"
      }
    ],
    "keybindings": [
      {
        "command": "llem.focusChat",
        "key": "cmd+l",
        "mac": "cmd+l"
      }
    ],
    "menus": {
      "editor/title": [
        {
          "command": "llem.openChat",
          "group": "navigation@99"
        }
      ],
      "editor/context": [
        {
          "command": "llem.explainSelection",
          "when": "editorHasSelection",
          "group": "1_modification"
        }
      ]
    },
    "viewsContainers": {
      "secondarySidebar": [
        {
          "id": "llem",
          "title": "LLeM",
          "icon": "assets/icon.svg"
        }
      ]
    },
    "views": {
      "llem": [
        {
          "type": "webview",
          "id": "llem.chat",
          "name": "LLeM",
          "icon": "assets/icon.svg"
        }
      ]
    },
    "configuration": {
      "title": "LLeM",
      "properties": {
        "llem.engineUrl": {
          "type": "string",
          "default": "http://127.0.0.1:11434",
          "description": "Local model endpoint. Point it at Rapid-MLX, LM Studio, or Ollama and let it cook."
        },
        "llem.defaultModel": {
          "type": "string",
          "default": "gemma4:e4b",
          "description": "Default model slug. Pick your fave and keep the flow moving."
        },
        "llem.performancePreset": {
          "type": "string",
          "enum": [
            "auto",
            "balanced",
            "large-local-26b"
          ],
          "default": "auto",
          "description": "Performance profile for prompt sizing and local Ollama budgets. Use large-local-26b when you want tighter limits for big local models."
        },
        "llem.requestTimeout": {
          "type": "number",
          "default": 300,
          "description": "How long LLeM waits before timing out, in seconds."
        },
        "llem.vaultPath": {
          "type": "string",
          "default": "",
          "description": "Optional path to your markdown vault. Leave it blank and LLeM spins up its own stash."
        },
        "llem.bridgeEnabled": {
          "type": "boolean",
          "default": false,
          "description": "Enable the local HTTP bridge on 127.0.0.1:4825 for external local tools. Keep this off unless you need it."
        },
        "llem.bridgeToken": {
          "type": "string",
          "default": "",
          "description": "Optional bearer token for the local HTTP bridge. When set, requests must include Authorization: Bearer <token> or X-LLeM-Token."
        },
        "llem.mcpEnabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable MCP server discovery and tool calls."
        },
        "llem.mcpServers": {
          "type": "object",
          "default": {},
          "description": "MCP servers registered directly in LLeM."
        },
        "llem.mcpConfigSources": {
          "type": "array",
          "default": [
            "llem",
            "workspace",
            "codex-global",
            "codex-project"
          ],
          "description": "MCP configuration sources to resolve."
        },
        "llem.mcpConfigPaths": {
          "type": "array",
          "default": [],
          "description": "Additional MCP JSON/TOML config paths to import."
        },
        "llem.mcpToolTimeoutSeconds": {
          "type": "number",
          "default": 60,
          "description": "Timeout for MCP server startup, tool listing, and tool calls."
        }
      }
    }
  },
  "scripts": {
    "vscode:prepublish": "npm run compile",
    "compile:ext": "esbuild src/extension.ts --bundle --platform=node --external:vscode --outfile=out/extension.js",
