        },
        "halfax.agentReasoningEffort": {
          "type": "string",
          "enum": ["low", "medium", "high", "off"],
          "default": "low",
          "description": "gpt-oss reasoning effort for agent-loop turns. lm1 (GPT-OSS-120B) reasons on every call (~18s); the agent loop is mostly mechanical tool-dispatch, so 'low' cuts latency with the loop's recovery guards catching the occasional shallow turn. Raise to 'medium'/'high' for harder autonomous planning; 'off' sends no override (model default). Sent as chat_template_kwargs.reasoning_effort; non-reasoning models ignore it."
        },
        "halfax.fimModel": {
          "type": "string",
          "default": "lm1",
          "description": "Model for inline FIM completions. Should be a coder model."
        },
