          "type": "string",
          "default": "0.1.0",
          "description": "Minimum backend version. Extension warns in the output channel if /api/status reports lower."
        },
        "halfax.updateUrl": {
          "type": "string",
          "default": "https://halfax.local/vscode/latest.json",
          "description": "Manifest URL polled by 'Check for Update'. Returns {version, vsixUrl}."
        },
        "halfax.completionEnabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable inline FIM completions."
        },
        "halfax.completionDebounceMs": {
          "type": "number",
          "default": 150,
          "description": "Debounce window for FIM requests in milliseconds."
        },
        "halfax.completionMaxTokens": {
          "type": "number",
          "default": 64,
          "description": "Max tokens to request per FIM completion."
        },
        "halfax.completionTimeoutMs": {
          "type": "number",
          "default": 5000,
          "description": "Timeout for a single FIM request before it is aborted."
        },
        "halfax.maxTokens": {
          "type": "number",
          "default": 2048,
          "description": "Max tokens per chat reply."
        },
        "halfax.temperature": {
          "type": "number",
          "default": 0.7,
          "description": "Chat sampling temperature."
        },
        "halfax.logLevel": {
          "type": "string",
          "enum": [
            "debug",
            "info",
            "warn",
            "error"
          ],
          "default": "info",
          "description": "Verbosity of the Halfax AI output channel."
        },
        "halfax.agentMaxIterations": {
          "type": "number",
          "default": 80,
          "minimum": 1,
          "maximum": 400,
          "description": "Maximum agent loop iterations (tool-call turns) before pausing. Default 80; raise for long multi-step tasks."
        },
        "halfax.agentConstrainedDecoding": {
          "type": "boolean",
          "default": true,
          "description": "Constrain agent-loop responses to a JSON schema via llama.cpp's json_schema field. Eliminates structural parse failures. Disable only if a future llama-server release rejects the schema shape."
        },
        "halfax.agentSelfConsistency": {
          "type": "boolean",
          "default": true,
          "description": "On agent `complete` turns, sample N candidate answers and pick the most-supported one (Jaccard-cluster vote, falling back to grounding against tool results). Lifts small-model accuracy on the high-stakes commit turn at the cost of N-1 extra non-streaming model calls per agent run."
        },
        "halfax.agentSelfConsistencyN": {
          "type": "number",
          "default": 3,
          "minimum": 1,
          "maximum": 5,
          "description": "Total candidates to sample on `complete` turns when self-consistency is on. 1 disables re-sampling; 3 is a good default."
        },
        "halfax.hooks": {
          "type": "object",
          "default": {},
          "description": "Lifecycle hooks. Each key is an event name; the value is a shell command (string) or array of commands to run via `bash -c`. Available env vars: HALFAX_EVENT, HALFAX_SESSION, HALFAX_MODE, HALFAX_TOOL, HALFAX_TOOL_OK, HALFAX_REASON, HALFAX_PAYLOAD (full JSON). Hooks are advisory — failures never block the foreground UX. 10s timeout per hook.",
          "properties": {
            "on-session-start": {
              "description": "Fires when a new chat session is minted (first user message after activation or New Session).",
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            },
            "on-tool-call": {
              "description": "Fires after every tool invocation completes. HALFAX_TOOL = qualified tool name; HALFAX_TOOL_OK = '1' on success, '0' on failure.",
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            },
            "on-stop": {
              "description": "Fires when chat or agent terminates. HALFAX_MODE = chat|agent; HALFAX_REASON = complete | ask_user | paused:<msg> | cancelled | error:<msg>.",
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            }
          },
          "additionalProperties": false
        },
        "halfax.mcpServers": {
          "type": "array",
          "default": [],
          "description": "MCP servers to auto-spawn over stdio. If empty, defaults to hal-ai-2 + homelab (mirroring ~/.continue/config.yaml). Each entry: { name, command, args?, env?, cwd? }.",
          "items": {
            "type": "object",
            "required": [
              "name",
              "command"
            ],
            "properties": {
              "name": {
                "type": "string"
              },
              "command": {
                "type": "string"
              },
              "args": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "env": {
