{
  "name": "taiga-mcp-extension",
  "displayName": "Taiga MCP Extension",
  "description": "Integrate Taiga (self-hosted or cloud) with VS Code. Browse projects and manage Epics, User Stories, Tasks, and Issues with rich editors. Includes a minimal MCP server auto-registered for Copilot tools.",
  "version": "1.1.1",
  "publisher": "AntonPavlenko",
  "author": "Anton Pavlenko",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/antpavlenko/taiga_mcp.git"
  },
  "bugs": {
    "url": "https://github.com/antpavlenko/taiga_mcp/issues"
  },
  "homepage": "https://github.com/antpavlenko/taiga_mcp#readme",
  "engines": {
    "vscode": "^1.102.0"
  },
  "categories": [
    "Other"
  ],
  "keywords": [
    "taiga",
    "agile",
    "project management",
    "epics",
    "user stories",
    "tasks",
    "issues",
    "mcp",
    "model context protocol"
  ],
  "galleryBanner": {
    "color": "#0d1117",
    "theme": "dark"
  },
  "main": "./dist/extension.js",
  "activationEvents": [
    "onStartupFinished"
  ],
  "icon": "media/taiga-emblem-mono-black-256.png",
  "contributes": {
    "mcpServerDefinitionProviders": [
      {
        "id": "taigaMcpProvider",
        "label": "Taiga MCP"
      }
    ],
    "viewsContainers": {
      "activitybar": [
        {
          "id": "taiga",
          "title": "Taiga",
          "icon": "media/taiga-emblem-dark.svg"
        }
      ]
    },
    "views": {
      "taiga": [
        {
          "id": "taigaControls",
          "name": "Controls",
          "type": "webview",
          "icon": "$(gear)"
        },
        {
          "id": "taigaEpics",
          "name": "Epics",
          "icon": "$(symbol-color)"
        },
        {
          "id": "taigaSprints",
          "name": "Sprints",
          "icon": "$(history)"
        },
        {
          "id": "taigaUserStories",
          "name": "User Stories",
          "icon": "$(list-selection)"
        },
        {
          "id": "taigaIssues",
          "name": "Issues",
          "icon": "$(bug)"
        }
      ]
    },
    "configuration": {
      "title": "Taiga",
      "properties": {
        "taiga.baseUrl": {
          "type": "string",
          "default": "",
          "description": "Taiga server base URL (e.g., https://your-taiga.example). The extension will auto-append /api/v1 if missing."
        },
        "taigaMcp.baseUrl": {
          "type": "string",
          "default": "",
          "description": "Base URL of your Taiga instance for MCP (no trailing slash, e.g. https://taiga.example.com)."
        },
        "taigaMcp.debug": {
          "type": "boolean",
          "default": false,
          "description": "Enable verbose debug for the Taiga MCP server (logs argv/env/config source on stderr and exposes taiga_debug_info tool)."
        },
        "taiga.maxPageSize": {
          "type": "number",
          "default": 50,
          "minimum": 10,
          "maximum": 200,
          "description": "Default page size for listing user stories."
        },
        "taiga.enableVerboseLogging": {
          "type": "boolean",
          "default": false,
          "description": "Enable verbose logging for diagnostics."
        }
      }
    },
    "commands": [
      { "command": "taiga.focusContainer", "title": "Taiga: Focus Taiga" },
      { "command": "taiga.focusControls", "title": "Taiga: Focus Controls" },
      { "command": "taiga.focusEpics", "title": "Taiga: Focus Epics" },
      { "command": "taiga.focusSprints", "title": "Taiga: Focus Sprints" },
      { "command": "taiga.focusUserStories", "title": "Taiga: Focus User Stories" },
      { "command": "taiga.focusIssues", "title": "Taiga: Focus Issues" },
      {
        "command": "taiga.connect",
        "title": "Connect"
      },
      {
        "command": "taiga.restartMcpServer",
        "title": "Taiga: Restart MCP Server"
      },
      {
        "command": "taiga.showMcpEnvDebug",
        "title": "Taiga: Show MCP Env (Debug)"
      },
      {
        "command": "taiga.openMcpServerDebugFile",
        "title": "Taiga: Open MCP Server Debug"
      },
      {
        "command": "taiga.setToken",
        "title": "Set / Update Token"
      },
      {
        "command": "taiga.selectProject",
        "title": "Select Project"
      },
      {
        "command": "taiga.refreshAll",
        "title": "Refresh"
      },
      {
        "command": "taiga.showDiagnostics",
        "title": "Show Diagnostics"
      },
      {
        "command": "taiga.toggleEpicFilter",
        "title": "Toggle Epic Filter"
      },
      {
        "command": "taiga.selectSprintFilter",
        "title": "Select Sprint"
      },
      {
        "command": "taiga.toggleShowClosedIssues",
        "title": "Toggle Show Closed Issues"
      },
      {
        "command": "taiga.createEpic",
        "title": "Create Epic…",
        "icon": "$(add)"
      },
      {
        "command": "taiga.editEpic",
        "title": "Edit Epic…",
        "icon": "$(edit)"
      },
      {
        "command": "taiga.deleteEpic",
        "title": "Delete Epic",
        "icon": "$(trash)"
      },
      {
        "command": "taiga.addStoriesToEpic",
        "title": "Add Stories to Epic",
        "icon": "$(link)"
      },
      {
        "command": "taiga.createSprint",
        "title": "Create Sprint…",
        "icon": "$(add)"
      },
      {
        "command": "taiga.editSprint",
        "title": "Edit Sprint…",
        "icon": "$(edit)"
      },
      {
        "command": "taiga.deleteSprint",
        "title": "Delete Sprint",
        "icon": "$(trash)"
      },
      {
        "command": "taiga.createUserStory",
        "title": "Create User Story…",
        "icon": "$(add)"
      },
      {
        "command": "taiga.editUserStory",
        "title": "Edit User Story…",
        "icon": "$(edit)"
      },
      {
        "command": "taiga.deleteUserStory",
        "title": "Delete User Story",
        "icon": "$(trash)"
      },
      {
        "command": "taiga.manageStoryTasks",
        "title": "Manage Tasks for Story",
        "icon": "$(tools)"
      },
      {
        "command": "taiga.createTaskForStory",
        "title": "Create Task for Story",
        "icon": "$(add)"
      },
      {
        "command": "taiga.createUserStoryForEpic",
        "title": "Create User Story for Epic",
        "icon": "$(add)"
      },
      {
        "command": "taiga.createIssue",
        "title": "Create Issue…",
        "icon": "$(add)"
      },
      {
        "command": "taiga.editIssue",
        "title": "Edit Issue…",
        "icon": "$(edit)"
      },
      {
        "command": "taiga.deleteIssue",
        "title": "Delete Issue",
        "icon": "$(trash)"
      }
    ],
    "menus": {
      "commandPalette": [
        { "command": "taiga.restartMcpServer", "when": "config.taigaMcp.debug" },
        { "command": "taiga.showMcpEnvDebug", "when": "config.taigaMcp.debug" },
        { "command": "taiga.openMcpServerDebugFile", "when": "config.taigaMcp.debug" },
        { "command": "taiga.focusContainer", "when": "false" },
        { "command": "taiga.focusControls", "when": "false" },
        { "command": "taiga.focusEpics", "when": "false" },
        { "command": "taiga.focusSprints", "when": "false" },
        { "command": "taiga.focusUserStories", "when": "false" },
        { "command": "taiga.focusIssues", "when": "false" }
      ],
      "view/title": [
        {
          "command": "taiga.refreshAll",
          "when": "view =~ /taiga(?!Controls).+/",
          "group": "navigation@2",
          "icon": "$(refresh)"
        },
        {
          "command": "taiga.createEpic",
          "when": "view == taigaEpics",
          "group": "navigation@99",
          "icon": "$(add)"
        },
        {
          "command": "taiga.createSprint",
          "when": "view == taigaSprints",
          "group": "navigation@99",
          "icon": "$(add)"
        },
        {
          "command": "taiga.createUserStory",
          "when": "view == taigaUserStories",
          "group": "navigation@99",
          "icon": "$(add)"
        },
        {
          "command": "taiga.createIssue",
          "when": "view == taigaIssues",
          "group": "navigation@99",
          "icon": "$(add)"
        }
      ],
      "view/item/context": [
        {
          "command": "taiga.createEpic",
          "when": "view == taigaEpics",
          "group": "navigation@1"
        },
        {
          "command": "taiga.editEpic",
          "when": "view == taigaEpics && viewItem == epic",
          "group": "navigation@2"
        },
        {
          "command": "taiga.deleteEpic",
          "when": "view == taigaEpics && viewItem == epic",
          "group": "navigation@3"
        },
        {
          "command": "taiga.createSprint",
          "when": "view == taigaSprints && viewItem == backlog",
          "group": "navigation@1"
        },
        {
          "command": "taiga.editSprint",
          "when": "view == taigaSprints && viewItem == sprint",
          "group": "navigation@2"
        },
        {
          "command": "taiga.deleteSprint",
          "when": "view == taigaSprints && viewItem == sprint",
          "group": "navigation@3"
        },
        {
          "command": "taiga.createUserStory",
          "when": "view == taigaUserStories",
          "group": "navigation@1"
        },
        {
          "command": "taiga.editUserStory",
          "when": "view == taigaUserStories && viewItem == userStory",
          "group": "navigation@2"
        },
        {
          "command": "taiga.deleteUserStory",
          "when": "view == taigaUserStories && viewItem == userStory",
          "group": "navigation@3"
        },
        {
          "command": "taiga.createIssue",
          "when": "view == taigaIssues",
          "group": "navigation@1"
        },
        {
          "command": "taiga.editIssue",
          "when": "view == taigaIssues && viewItem == issue",
