  "version": "0.1.0",
  "description": "Model Context Protocol server that drives a RUNNING GMPI standalone plugin app — read and set parameters, inject MIDI, click and drag its GUI, screenshot it, and render its audio offline.",
  "license": "ISC",
  "author": "Jeff McClintock",
  "type": "module",
  "bin": {
    "gmpi-standalone-mcp": "dist/index.js"
  },
  "main": "dist/index.js",
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js",
    "dev": "tsx src/index.ts",
    "prepublishOnly": "npm run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JeffMcClintock/GMPI_Wrappers.git",
    "directory": "mcp"
  },
  "bugs": {
    "url": "https://github.com/JeffMcClintock/GMPI_Wrappers/issues"
  },
  "homepage": "https://github.com/JeffMcClintock/GMPI_Wrappers/tree/main/mcp#readme",
  "keywords": [
    "gmpi",
    "mcp",
    "model-context-protocol",
    "claude",
    "audio",
    "audio-plugin",
    "vst",
    "synthesizer"
  ],
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "tsx": "^4.19.0",
    "typescript": "^5.6.0"
  },
  "engines": {
    "node": ">=18"
  }
}

