        {
          "command": "bpscm.update",
          "group": "navigation",
          "when": "scmProvider == bpscm"
        },
        {
          "command": "bpscm.stageAll",
          "group": "1_staging",
          "when": "scmProvider == bpscm"
        },
        {
          "command": "bpscm.unstageAll",
          "group": "1_staging",
          "when": "scmProvider == bpscm"
        },
        {
          "command": "bpscm.checkinAll",
          "group": "2_checkin",
          "when": "scmProvider == bpscm"
        }
      ],
      "scm/resourceGroup/context": [
        {
          "command": "bpscm.stageAll",
          "when": "scmProvider == bpscm && scmResourceGroup == changes",
          "group": "inline"
        },
        {
          "command": "bpscm.unstageAll",
          "when": "scmProvider == bpscm && scmResourceGroup == staged",
          "group": "inline"
        }
      ],
      "scm/resourceState/context": [
        {
          "command": "bpscm.stage",
          "when": "scmProvider == bpscm && scmResourceGroup == changes",
          "group": "inline"
        },
        {
          "command": "bpscm.unstage",
          "when": "scmProvider == bpscm && scmResourceGroup == staged",
          "group": "inline"
        },
        {
          "command": "bpscm.openFile",
          "when": "scmProvider == bpscm",
          "group": "inline"
        },
        {
          "command": "bpscm.openChange",
          "when": "scmProvider == bpscm",
          "group": "navigation"
        },
        {
          "command": "bpscm.revertChange",
          "when": "scmProvider == bpscm",
          "group": "1_modification"
        },
        {
          "command": "bpscm.showFileHistory",
          "when": "scmProvider == bpscm",
          "group": "2_history"
        },
        {
          "command": "bpscm.showDiffAgainst",
          "when": "scmProvider == bpscm && bpscm.pendingMergeActive",
          "group": "2_history"
        }
      ],
      "view/item/context": [
        {
          "command": "bpscm.switchBranch",
          "when": "view == bpscm.branchesView && viewItem == branch",
          "group": "1_navigation@1"
        },
        {
          "command": "bpscm.copyBranchSpec",
          "when": "view == bpscm.branchesView && (viewItem == branch || viewItem == branch:current)",
          "group": "2_clipboard@1"
        },
        {
          "command": "bpscm.deleteBranch",
          "when": "view == bpscm.branchesView && viewItem == branch",
          "group": "3_modification@1"
        },
        {
          "command": "bpscm.showMergeContributors",
          "when": "view == bpscm.pendingMergeView && (viewItem == pendingMerge.conflict || viewItem == pendingMerge.autoResolved)",
          "group": "1_inspect@1"
        },
        {
          "command": "bpscm.diffAgainstMergeSrc",
          "when": "view == bpscm.pendingMergeView && (viewItem == pendingMerge.conflict || viewItem == pendingMerge.autoResolved)",
          "group": "2_diff@1"
        },
        {
          "command": "bpscm.diffAgainstMergeDst",
          "when": "view == bpscm.pendingMergeView && (viewItem == pendingMerge.conflict || viewItem == pendingMerge.autoResolved)",
          "group": "2_diff@2"
        },
        {
          "command": "bpscm.diffAgainstMergeSrc",
          "when": "view == bpscm.pendingMergeView && (viewItem == pendingMerge.conflict || viewItem == pendingMerge.autoResolved)",
          "group": "inline@1"
        },
        {
          "command": "bpscm.diffAgainstMergeDst",
          "when": "view == bpscm.pendingMergeView && (viewItem == pendingMerge.conflict || viewItem == pendingMerge.autoResolved)",
          "group": "inline@2"
        },
        {
          "command": "bpscm.openCodeReview",
          "when": "view == bpscm.codeReviewsView && viewItem == codeReview",
          "group": "navigation"
        },
        {
          "command": "bpscm.inspectReviewComments",
          "when": "view == bpscm.codeReviewsView && viewItem == codeReview",
          "group": "navigation"
        },
        {
          "command": "bpscm.inspectReviewComments",
          "when": "view == bpscm.codeReviewsView && viewItem == codeReview",
          "group": "inline@1"
        },
        {
          "command": "bpscm.openCodeReview",
          "when": "view == bpscm.codeReviewsView && viewItem == codeReview",
          "group": "inline@2"
        }
      ],
      "view/title": [
        {
          "command": "bpscm.createBranch",
          "when": "view == bpscm.branchesView",
          "group": "navigation@1"
        },
        {
          "command": "bpscm.refreshBranches",
          "when": "view == bpscm.branchesView",
          "group": "navigation@2"
        },
        {
          "command": "bpscm.abortPendingMerge",
          "when": "view == bpscm.pendingMergeView",
          "group": "navigation@1"
        },
        {
          "command": "bpscm.clearPendingMerge",
          "when": "view == bpscm.pendingMergeView",
          "group": "navigation@2"
        },
        {
          "command": "bpscm.clearUncommittedMerge",
          "when": "view == bpscm.pendingMergeView",
          "group": "navigation@3"
        },
        {
          "command": "bpscm.refreshPendingMerge",
          "when": "view == bpscm.pendingMergeView",
          "group": "navigation@4"
        },
        {
          "command": "bpscm.createCodeReview",
          "when": "view == bpscm.codeReviewsView",
          "group": "navigation@1"
        },
        {
          "command": "bpscm.refreshCodeReviews",
          "when": "view == bpscm.codeReviewsView",
          "group": "navigation@2"
        },
        {
          "command": "bpscm.nextReviewComment",
          "when": "view == bpscm.reviewCommentsView",
          "group": "navigation"
        },
        {
          "command": "bpscm.prevReviewComment",
          "when": "view == bpscm.reviewCommentsView",
          "group": "navigation"
        },
        {
          "command": "bpscm.exportReviewAudit",
          "when": "view == bpscm.reviewCommentsView",
          "group": "navigation"
        }
      ],
      "editor/title": [
        {
          "command": "bpscm.openFile",
          "when": "isInDiffEditor && resourceScheme == file && bpscm.isActive",
          "group": "navigation"
        },
        {
          "command": "bpscm.showFileHistory",
          "when": "bpscm.isActive",
          "group": "navigation"
        },
        {
          "command": "bpscm.annotateFile",
          "when": "bpscm.isActive",
          "group": "navigation"
        }
      ]
    },
    "mcpServerDefinitionProviders": [
      {
        "id": "bpscmMcp",
        "label": "BetterPSCM"
      }
    ],
    "views": {
      "scm": [
        {
          "id": "bpscm.branchesView",
          "name": "Branches",
          "when": "bpscm.isActive"
        },
        {
          "id": "bpscm.pendingMergeView",
          "name": "Pending Merge",
          "when": "bpscm.isActive && bpscm.pendingMergeActive"
        },
        {
          "id": "bpscm.historyGraphView",
          "type": "webview",
          "name": "Graph",
          "when": "bpscm.isActive"
        },
        {
          "id": "bpscm.codeReviewsView",
          "name": "Code Reviews",
          "when": "bpscm.isActive"
        },
        {
          "id": "bpscm.reviewCommentsView",
          "name": "Review Comments",
          "when": "bpscm.isActive && bpscm.reviewActive"
        }
      ]
    },
    "configuration": {
      "title": "BetterPSCM",
      "properties": {
        "bpscm.serverUrl": {
          "type": "string",
          "default": "",
          "description": "Plastic SCM server URL (e.g., https://cloud.plasticscm.com or http://localhost:7178)"
        },
        "bpscm.organizationName": {
          "type": "string",
          "default": "",
          "description": "Organization name"
        },
        "bpscm.repositoryName": {
          "type": "string",
          "default": "",
          "description": "Repository name"
        },
        "bpscm.workspaceGuid": {
          "type": "string",
          "default": "",
          "description": "Workspace GUID (auto-detected if possible)"
        },
        "bpscm.pollInterval": {
          "type": "number",
          "default": 3000,
          "minimum": 1000,
          "description": "Status polling interval in milliseconds"
        },
        "bpscm.showPrivateFiles": {
          "type": "boolean",
          "default": true,
          "description": "Show private (unversioned) files in changes list"
        },
        "bpscm.mcp.enabled": {
          "type": "boolean",
          "default": false,
          "description": "Enable MCP server for AI agent integration"
        },
        "bpscm.graph.followActiveFile": {
          "type": "boolean",
          "default": true,
          "description": "When enabled, opening a file (e.g. from the Search view) automatically filters the history graph to changesets that touched that file."
        },
        "bpscm.cache.prewarm.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Pre-fetch base-revision content for every changed file after each status poll, so the first click on a file in the Changes view opens its diff instantly. Disable if cm.exe shows lock contention with status polling."
        },
        "bpscm.cache.prewarm.concurrency": {
          "type": "number",
          "default": 2,
          "minimum": 1,
          "maximum": 6,
          "description": "Maximum number of background cm.exe calls the prewarmer may run in parallel. Higher values speed up bulk prewarm but contend with the status poller for workspace locks. Takes effect after extension reload."
        },
        "bpscm.cache.prewarm.maxFileBytes": {
          "type": "number",
          "default": 1048576,
          "minimum": 0,
          "description": "Working-copy files larger than this (bytes) skip prewarm. Default 1 MiB protects the cache from multi-MB Unity scene/prefab text diffs."
        },
        "bpscm.cache.prewarm.historyWindow": {
          "type": "number",
          "default": 10,
          "minimum": 1,
          "maximum": 100,
          "description": "How many of the newest visible history-graph rows have their diffs prewarmed after each render."
        }
      }
    }
