				"title": "%command.acceptInput.title%",
				"category": "%configuration.title%"
			},
			{
				"command": "zoo-code.toggleAutoApprove",
				"title": "%command.toggleAutoApprove.title%",
				"category": "%configuration.title%"
			}
		],
		"menus": {
			"editor/context": [
				{
					"submenu": "zoo-code.contextMenu",
					"group": "1"
				}
			],
			"zoo-code.contextMenu": [
				{
					"command": "zoo-code.addToContext",
					"group": "1_actions@1"
				},
				{
					"command": "zoo-code.explainCode",
					"group": "1_actions@2"
				},
				{
					"command": "zoo-code.improveCode",
					"group": "1_actions@3"
				}
			],
			"terminal/context": [
				{
					"submenu": "zoo-code.terminalMenu",
					"group": "2"
				}
			],
			"zoo-code.terminalMenu": [
				{
					"command": "zoo-code.terminalAddToContext",
					"group": "1_actions@1"
				},
				{
					"command": "zoo-code.terminalFixCommand",
					"group": "1_actions@2"
				},
				{
					"command": "zoo-code.terminalExplainCommand",
					"group": "1_actions@3"
				}
			],
			"view/title": [
				{
					"command": "zoo-code.plusButtonClicked",
					"group": "navigation@1",
					"when": "view == zoo-code.SidebarProvider"
				},
				{
					"command": "zoo-code.settingsButtonClicked",
					"group": "navigation@2",
					"when": "view == zoo-code.SidebarProvider"
				},
				{
					"command": "zoo-code.marketplaceButtonClicked",
					"group": "navigation@3",
					"when": "view == zoo-code.SidebarProvider"
				},
				{
					"command": "zoo-code.historyButtonClicked",
					"group": "overflow@1",
					"when": "view == zoo-code.SidebarProvider"
				},
				{
					"command": "zoo-code.popoutButtonClicked",
					"group": "overflow@2",
					"when": "view == zoo-code.SidebarProvider"
				}
			],
			"editor/title": [
				{
					"command": "zoo-code.plusButtonClicked",
					"group": "navigation@1",
					"when": "activeWebviewPanelId == zoo-code.TabPanelProvider"
				},
				{
					"command": "zoo-code.settingsButtonClicked",
					"group": "navigation@2",
					"when": "activeWebviewPanelId == zoo-code.TabPanelProvider"
				},
				{
					"command": "zoo-code.marketplaceButtonClicked",
					"group": "navigation@3",
					"when": "activeWebviewPanelId == zoo-code.TabPanelProvider"
				},
				{
					"command": "zoo-code.historyButtonClicked",
					"group": "overflow@1",
					"when": "activeWebviewPanelId == zoo-code.TabPanelProvider"
				},
				{
					"command": "zoo-code.popoutButtonClicked",
					"group": "overflow@2",
					"when": "activeWebviewPanelId == zoo-code.TabPanelProvider"
				}
			]
		},
		"keybindings": [
			{
				"command": "zoo-code.addToContext",
				"key": "cmd+k cmd+a",
				"mac": "cmd+k cmd+a",
				"win": "ctrl+k ctrl+a",
				"linux": "ctrl+k ctrl+a",
				"when": "editorTextFocus && editorHasSelection"
			},
			{
				"command": "zoo-code.toggleAutoApprove",
				"key": "cmd+alt+a",
				"mac": "cmd+alt+a",
				"win": "ctrl+alt+a",
				"linux": "ctrl+alt+a"
			}
		],
		"submenus": [
			{
				"id": "zoo-code.contextMenu",
				"label": "%views.contextMenu.label%"
