		"viewsContainers": {
			"activitybar": [
				{
					"id": "taskmaster",
					"title": "TaskMaster",
					"icon": "assets/sidebar-icon.svg"
				}
			]
		},
		"views": {
			"taskmaster": [
				{
					"id": "taskmaster.welcome",
