        },
        "skillsReviewAndPolish.model": {
          "type": "string",
          "default": "",
          "markdownDescription": "Analysis model **id**. Empty = use the provider default / selected Copilot model, which is recommended for first run with `vscode-lm`. Use the _Skills Review: Select Analysis Model_ command to choose a specific model. **The picker marks the currently recommended OpenRouter models with ⭐.** See `scripts/e56-corpus-rescan-multimodel.mjs` and the [Recommended OpenRouter Models](docs/USER-GUIDE.md#recommended-openrouter-models) table for the experiment that produced the recommendations."
        },
        "skillsReviewAndPolish.pickerSortBy": {
          "type": "string",
          "enum": [
            "price",
            "multiplier",
            "name"
          ],
          "default": "price",
          "description": "How to sort models in the picker. 'price' = per-million-token cost (cheapest first), 'multiplier' = Copilot premium request multiplier (lowest first), 'name' = alphabetical."
        },
        "skillsReviewAndPolish.modelDisplayName": {
          "type": "string",
          "default": "",
          "markdownDescription": "_(Read-only — set automatically by the model picker.)_ Friendly name of the currently selected analysis model, shown here so you can see what `skillsReviewAndPolish.model` refers to without re-opening the picker."
        },
        "skillsReviewAndPolish.deepModel": {
          "type": "string",
          "default": "",
          "description": "Model for the contradictions/deep wave. Empty = same as analysis model/provider default. **OpenRouter recommendation:** `deepseek/deepseek-chat-v3` paired with `google/gemini-2.5-flash-lite` as the standard model (see `scripts/e56-corpus-rescan-multimodel.mjs` and the [Recommended OpenRouter Models](docs/USER-GUIDE.md#recommended-openrouter-models) table in USER-GUIDE.md)."
        },
        "skillsReviewAndPolish.fixModel": {
          "type": "string",
          "default": "",
          "description": "Model for surgical fixes. A reasoning model is recommended. Empty = same as analysis model."
        },
        "skillsReviewAndPolish.fixModelDisplayName": {
          "type": "string",
          "default": "",
          "markdownDescription": "_(Read-only - set automatically by the model picker.)_ Friendly name of the currently selected fix model, shown here so you can see what `skillsReviewAndPolish.fixModel` refers to without re-opening the picker."
        },
        "skillsReviewAndPolish.external.structuredOutput": {
          "type": [
            "boolean",
            "string"
          ],
          "enum": [
            true,
            false,
            "schema",
            "true",
            "false"
          ],
          "default": "schema",
          "markdownDescription": "Structured JSON response mode for external providers. **Default: `schema`** — sends a strict JSON schema via `response_format: { \"type\": \"json_schema\" }` so OpenAI, Gemini, Anthropic (Sonnet 4.5+), and Fireworks all return the analyzer's expected shape with no truncation. Set to `true` to use the legacy `response_format: { \"type\": \"json_object\" }` (only recommended for models that validated well under that mode). Set to `false` to omit `response_format` entirely (use only when both shapes are rejected). See `docs/plan/research/structured-output-provider-surfaces.md` for the probe matrix that informed the default."
        },
        "skillsReviewAndPolish.external.requestTimeoutMs": {
          "type": "number",
          "default": 120000,
          "minimum": 5000,
          "maximum": 600000,
          "description": "Maximum wall-clock time for a single external-provider HTTP request before it is cancelled."
        },
        "skillsReviewAndPolish.external.maxResponseTokens": {
          "type": "number",
          "default": 16384,
          "minimum": 512,
          "maximum": 262144,
          "description": "Maximum output tokens requested from external providers (`max_tokens`). Increase this if long prompts are getting cut off."
        },
        "skillsReviewAndPolish.external.adaptiveResponseTokens": {
          "type": "boolean",
          "default": false,
          "description": "When enabled, scale response `max_tokens` per request from prompt length (bounded by min/max settings) instead of always using a fixed value."
        },
        "skillsReviewAndPolish.external.adaptiveMaxResponseTokens": {
          "type": "number",
          "default": 65536,
          "minimum": 512,
          "maximum": 262144,
          "description": "Upper bound for adaptive response-token sizing. Only used when external.adaptiveResponseTokens is enabled. Defaults higher than external.maxResponseTokens so long prompts can request more output than the fixed-mode ceiling."
        },
        "skillsReviewAndPolish.external.minAdaptiveResponseTokens": {
          "type": "number",
          "default": 4096,
          "minimum": 512,
          "maximum": 262144,
          "description": "Lower bound for adaptive response-token sizing. Ignored unless external.adaptiveResponseTokens is enabled."
        },
        "skillsReviewAndPolish.external.adaptiveCharsPerToken": {
          "type": "number",
          "default": 8,
          "minimum": 1,
          "maximum": 128,
          "description": "Heuristic scale used by adaptive response-token sizing: desired tokens = ceil(promptChars / this value). Lower values request more output tokens."
        },
        "skillsReviewAndPolish.analysisMode": {
          "type": "string",
          "enum": [
            "single",
            "focused",
            "multiWave"
          ],
          "default": "multiWave",
          "description": "'multiWave' runs 6 focused passes (best quality). 'focused' runs 2 high-signal passes — contradictions + ambiguities (faster, good quality). 'single' runs one combined prompt (cheapest/fastest, lower recall)."
        },
        "skillsReviewAndPolish.filterFindings": {
          "type": "boolean",
          "default": true,
          "markdownDescription": "Run the deterministic finding post-processor on analyzer output before reporting. **Recommended: keep on.** The post-processor suppresses false positives the LLM waves produce from reading project rules literally (e.g. flagging 'may' as weak obligation, flagging 'must not' as ambiguous, flagging a numbered procedure as unordered). **Off** if you want the raw analyzer output for debugging or for fuzz-testing your own prompts. The post-processor is purely deterministic — it does not change the underlying LLM behavior, only the finding list presented to you."
        },
        "skillsReviewAndPolish.enabledWaves": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "contradictions",
              "ambiguities",
              "persona",
              "structural",
              "coverage",
              "hygiene"
            ]
          },
          "default": [
            "contradictions",
            "ambiguities",
            "persona",
            "structural",
            "coverage",
            "hygiene"
          ],
          "description": "Which analysis categories (waves) to run."
        },
