        "skillsReviewAndPolish.fixStrategy": {
          "type": "string",
          "enum": [
            "subtractive",
            "additive"
          ],
          "default": "subtractive",
          "description": "'subtractive' tightens by removing vagueness; 'additive' appends a concrete clause (append-only)."
        },
        "skillsReviewAndPolish.fixLoopMaxIterations": {
          "type": "number",
          "default": 3,
          "minimum": 1,
          "maximum": 10,
          "description": "Max fix-then-rescan iterations when fixMode is 'loop'."
        },
        "skillsReviewAndPolish.fix.semanticCheck": {
          "type": "boolean",
          "default": false,
          "description": "Run an extra semantic-equivalence judge on each fix (extra API call)."
        },
        "skillsReviewAndPolish.fix.selfCritique": {
          "type": "boolean",
          "default": false,
          "description": "Audit each content-adding fix for fabricated facts (extra API call). Forced on for additive fixes."
        },
        "skillsReviewAndPolish.fix.referenceGrounding": {
          "type": "boolean",
          "default": true,
          "description": "Use a sibling references/ directory to ground factual fragments when fixing."
        },
        "skillsReviewAndPolish.fix.guard.upperBoundMultiplier": {
          "type": "number",
          "default": 1.5,
          "minimum": 1,
          "maximum": 3,
          "markdownDescription": "Maximum growth factor for fix output. Fixes exceeding this limit are rejected. For ambiguity-llm subtractive fixes, the effective limit is 1.1x regardless of this setting. For additive ambiguity fixes, the limit is `max(original × multiplier, original + 80)` to guarantee room for concrete clauses."
